/* Shardwild v30 - 12-step "Shardwild cleared" bar + new crown (Sprites). Generated by src/export.py. NOT wired in.
 *
 * Replaces CLEAR_BAR (8 steps). Same raw pieces (paint 1:1, no mkSprite) plus 12 diamond pips under the bar (one per event) and a
 * redrawn crown (pointed peaks + gems, 11x8) so crownOff reads as a crown, not a battlement.
 * h = 18: bar rows 0-11 as before, crystal pips 5x7 at pipY=11 (overlapping the bar's empty bottom row). Crown drawn at (W+2, 2).
 * CLEAR_BAR_12.build(W,kills) -> rows, CLEAR_BAR_12.toCanvas(W,kills) -> canvas.  NOTE the 2nd arg is the KILL COUNT 0..12, not a fraction.
 * Game changes: game.js ~6257 CLEAR_BAR.toCanvas(120,k/8) -> CLEAR_BAR_12.toCanvas(120,k); clearPct (~5123) clamp/divide by 12 not 8;
 *   cache the canvas per kill count (13 states). Leave 18px of height for it instead of 12.
 */
const CLEAR_BAR_12={
 "pal":{"k":"#0d0b12","f":"#5a4a70","F":"#30263e","B":"#1e1628","d":"#120e18","n":"#7a6898","c":"#8a3ad0","C":"#ff4fa8","W":"#ffd6ec","P":"#a01860","r":"#ff4fa8","R":"#ff9ccc","w":"#fff0f8","g":"#4a4652","G":"#7a7684","y":"#ffd34a","o":"#b8801c","Y":"#fff3b0","D":"#3a2a4a","e":"#5a4a6a"},
 "h":18,
 "capW":8,
 "fillRow":4,
 "segments":12,
 "leftCap":["....kW..","...kWCkk","..kWCCkf",".kWCCCkF","kWCCCWkk","kCCCCWkk","kccccckk","kPcccckk",".kPccckF","..kPcckB","...kPckk","....kP.."],
 "rightCap":["..Wk....","kkCWk...","fkCCWk..","FkCCCWk.","kkWCCCWk","kkWCCCCk","kkccccck","kkccccPk","FkcccPk.","BkccPk..","kkcPk...","..Pk...."],
 "midFrame":["....","kkkk","fffn","FFFF","dddd","dddd","dddd","dddd","FFFF","BBBB","kkkk","...."],
 "fill":["RRRR","rrrr","rrrr","PPPP"],
 "fillCap":["Rw","rw","rw","Pr"],
 "notch":[".",".","n",".","k",".",".","k",".","n",".","."],
 "pipOn":["..k..",".kWk.","kWCCk","kCCPk","kCPPk",".kPk.","..k.."],
 "pipOff":["..k..",".kGk.","kGggk","kggek","kgeek",".kek.","..k.."],
 "pipY":11,
 "crownOn":["k....k....k","kk..kWk..kk","kWk.kyk.kWk","kyykyyykyyk","kyyyyyyyyyk","kyCyyRyyCyk","koooooooook","kkkkkkkkkkk"],
 "crownOff":["k....k....k","kk..kGk..kk","kGk.kgk.kGk","kggkgggkggk","kgggggggggk","kgeggeggegk","kDDDDDDDDDk","kkkkkkkkkkk"]
};
CLEAR_BAR_12.build=function(W,kills){
  const B=CLEAR_BAR_12,C=B.capW,inner=W-2*C,rows=[],seg=B.segments,k=Math.max(0,Math.min(seg,kills)),frac=k/seg;
  for(let y=0;y<12;y++){let r=B.leftCap[y];for(let i=0;i<inner;i++)r+=B.midFrame[y][i%4];rows.push((r+B.rightCap[y]).split(''));}
  const n=Math.round(inner*frac);
  for(let i=0;i<n;i++)for(let j=0;j<4;j++)rows[B.fillRow+j][C+i]=B.fill[j][i%4];
  if(n>=2&&n<inner)for(let j=0;j<4;j++)for(let q=0;q<2;q++)rows[B.fillRow+j][C+n-2+q]=B.fillCap[j][q];
  for(let s=1;s<seg;s++){const x=C+Math.round(inner*s/seg);
    for(let y=0;y<12;y++){let ch=B.notch[y];if(ch==='.')continue;if(y>=4&&y<=7&&ch==='k'&&x<C+n-2)ch='P';rows[y][x]=ch;}}
  for(let y=12;y<B.h;y++)rows.push(new Array(W).fill('.'));
  for(let s=0;s<seg;s++){const cx=C+Math.round(inner*(s+0.5)/seg),p=s<k?B.pipOn:B.pipOff;
    for(let y=0;y<p.length;y++)for(let x=0;x<p[y].length;x++)if(p[y][x]!=='.')rows[B.pipY+y][cx-2+x]=p[y][x];}
  return rows.map(r=>r.join(''));
};
CLEAR_BAR_12.toCanvas=function(W,kills){
  const B=CLEAR_BAR_12,rows=B.build(W,kills),cr=kills>=B.segments?B.crownOn:B.crownOff;
  const c=document.createElement('canvas');c.width=W+2+cr[0].length;c.height=B.h;const g=c.getContext('2d');
  const put=(rs,x0,y0)=>{for(let y=0;y<rs.length;y++)for(let x=0;x<rs[y].length;x++){const ch=rs[y][x];if(ch!=='.'){g.fillStyle=B.pal[ch];g.fillRect(x0+x,y0+y,1,1);}}};
  put(rows,0,0);put(cr,W+2,2);return c;
};
if(typeof module!=='undefined')module.exports={CLEAR_BAR_12};
